#!/usr/bin/env python3
"""Read-only HK diagnostic collector. Never emits raw logs/headers/body/SQL.

Run locally on HK via the existing SSH observation channel. No remote execution,
deployment, service changes, database queries, or shell=True are implemented.
"""
from __future__ import annotations

import argparse
import collections
import datetime as dt
import hashlib
import json
import math
import re
import selectors
import subprocess
import sys
import time

PROJECT = "go-822-staging"
RUN_ID = "hk3-mu67txw3-2d1cc6"
EARLIEST = "2026-09-18T00:23:00Z"
MAX_WINDOW_SECONDS = 7200
MAX_LOG_BYTES = 64 * 1024 * 1024
MAX_LINE_BYTES = 128 * 1024
MAX_SAMPLES = 100000
ID_RE = re.compile(r"(?<![A-Za-z0-9-])" + re.escape(RUN_ID) + r"-[0-9a-z]+(?![A-Za-z0-9-])")
ACCESS_RE = re.compile(r'"(?:GET|POST|PUT|PATCH|DELETE|HEAD|OPTIONS)\s+[^"\r\n]+\s+HTTP/\d(?:\.\d)?"\s+(\d{3})(?:\s|$)')
FRAME_RE = re.compile(r'^\s*File "([^"]{1,500})", line ([0-9]{1,6})(?:,|$)')
EXCEPTIONS = (
    ("SQLALCHEMY_QUEUE_POOL_TIMEOUT", re.compile(r"QueuePool limit|QueuePoolTimeout|QueuePool.*timed out")),
    ("SQLALCHEMY_TIMEOUT_ERROR", re.compile(r"\bsqlalchemy\.exc\.TimeoutError\b")),
    ("OPERATIONAL_ERROR", re.compile(r"\bOperationalError\b")),
    ("INTERFACE_ERROR", re.compile(r"\bInterfaceError\b")),
    ("INTEGRITY_ERROR", re.compile(r"\bIntegrityError\b")),
    ("PROGRAMMING_ERROR", re.compile(r"\bProgrammingError\b")),
    ("DBAPI_ERROR", re.compile(r"\bDBAPIError\b")),
    ("CONNECTION_RESET_ERROR", re.compile(r"\bConnectionResetError\b")),
    ("BROKEN_PIPE_ERROR", re.compile(r"\bBrokenPipeError\b")),
    ("CANCELLED_ERROR", re.compile(r"\bCancelledError\b")),
    ("TIMEOUT_ERROR", re.compile(r"\bTimeoutError\b")),
    ("HTTP_EXCEPTION", re.compile(r"\bHTTPException\b")),
    ("EXCEPTION_GROUP", re.compile(r"\bExceptionGroup\b")),
    ("RUNTIME_ERROR", re.compile(r"\bRuntimeError\b")),
    ("VALUE_ERROR", re.compile(r"\bValueError\b")),
    ("KEY_ERROR", re.compile(r"\bKeyError\b")),
    ("TYPE_ERROR", re.compile(r"\bTypeError\b")),
    ("ATTRIBUTE_ERROR", re.compile(r"\bAttributeError\b")),
    ("ASSERTION_ERROR", re.compile(r"\bAssertionError\b")),
)
FRAMEWORKS = {
    "go_hotel": "APPLICATION", "sqlalchemy": "SQLALCHEMY", "uvicorn": "UVICORN",
    "starlette": "STARLETTE", "fastapi": "FASTAPI", "anyio": "ANYIO", "asyncio": "ASYNCIO",
    "httpx": "HTTPX", "httpcore": "HTTPCORE", "redis": "REDIS", "psycopg": "PSYCOPG",
    "psycopg2": "PSYCOPG2", "pydantic": "PYDANTIC",
}


def digest(value: bytes) -> str:
    return hashlib.sha256(value).hexdigest()


def utc(value: str) -> dt.datetime:
    if not re.fullmatch(r"\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d(?:\.\d{1,6})?Z", value):
        raise ValueError("UTC_TIMESTAMP_REQUIRED")
    return dt.datetime.fromisoformat(value[:-1] + "+00:00")


def command(argv: list[str], timeout: int = 15) -> tuple[bytes, dict]:
    try:
        result = subprocess.run(argv, capture_output=True, timeout=timeout, check=False)
        return result.stdout, {"exit_code": result.returncode, "stderr_sha256": digest(result.stderr), "stderr_bytes": len(result.stderr)}
    except subprocess.TimeoutExpired:
        return b"", {"error": "COMMAND_TIMEOUT"}
    except OSError:
        return b"", {"error": "COMMAND_UNAVAILABLE"}


def percentile(values: list[float], q: float):
    if not values:
        return None
    a = sorted(values)
    return round(a[max(0, math.ceil(len(a) * q) - 1)], 3)


class Aggregate:
    def __init__(self):
        self.count = 0
        self.statuses = collections.Counter()
        self.latencies = []
        self.latency_total = 0
        self.latency_max = None
        self.latency_sum = 0.0

    def add(self, status, latency):
        self.count += 1
        if status is not None:
            self.statuses[str(status)] += 1
        if latency is not None:
            self.latency_total += 1
            self.latency_sum += latency
            self.latency_max = max(self.latency_max or 0, latency)
            if len(self.latencies) < MAX_SAMPLES:
                self.latencies.append(latency)

    def report(self):
        exact = self.latency_total <= MAX_SAMPLES
        return {"access_events": self.count, "statuses": dict(self.statuses),
                "latency_observations": self.latency_total,
                "latency_quantiles_complete": exact,
                "latency_p50_ms": percentile(self.latencies, .5) if exact else None,
                "latency_p95_ms": percentile(self.latencies, .95) if exact else None,
                "latency_p99_ms": percentile(self.latencies, .99) if exact else None,
                "latency_mean_ms": round(self.latency_sum / self.latency_total, 3) if self.latency_total else None,
                "latency_max_ms": self.latency_max}


def request_ids(obj):
    """Read only known ID locations. Never return other header values."""
    result = []
    if not isinstance(obj, dict):
        return result
    for key in ("request_id", "requestId", "request-id"):
        value = obj.get(key)
        if isinstance(value, str):
            result.append(value)
    request = obj.get("request")
    if isinstance(request, dict):
        for key in ("request_id", "id"):
            value = request.get(key)
            if isinstance(value, str):
                result.append(value)
    for headers in [obj.get("resp_headers"), obj.get("headers"), request.get("headers") if isinstance(request, dict) else None]:
        if not isinstance(headers, dict):
            continue
        for key, value in headers.items():
            if str(key).lower() in {"x-request-id", "request-id"}:
                if isinstance(value, str):
                    result.append(value)
                elif isinstance(value, list):
                    result.extend(v for v in value if isinstance(v, str))
    return result


def correlation(ids):
    if any(ID_RE.fullmatch(v) for v in ids):
        return "matched_run"
    return "other_request_id" if ids else "unattributed_no_request_id"


def safe_number(value):
    if isinstance(value, (int, float)) and not isinstance(value, bool) and math.isfinite(value) and value >= 0:
        return float(value)
    return None


def access_event(obj, service):
    if not isinstance(obj, dict):
        return None
    status = obj.get("status", obj.get("status_code"))
    if not isinstance(status, int) or isinstance(status, bool) or not 100 <= status <= 599:
        return None
    latency = None
    for key in ("elapsed_ms", "latency_ms", "duration_ms"):
        value = safe_number(obj.get(key))
        if value is not None:
            latency = value
            break
    if latency is None and service == "caddy":
        duration = safe_number(obj.get("duration"))
        if duration is not None:
            latency = duration * 1000
    return status, latency, correlation(request_ids(obj))


class LogSummary:
    def __init__(self, service):
        self.service = service
        self.lines = 0
        self.bytes = 0
        self.json_lines = 0
        self.unparsed = 0
        self.overlong = 0
        self.groups = {key: Aggregate() for key in ("matched_run", "other_request_id", "unattributed_no_request_id")}
        self.exception_lines = collections.Counter()
        self.exception_hashes = collections.defaultdict(list)
        self.frames = collections.Counter()
        self.matched_request_ids = set()

    def consume(self, raw):
        self.lines += 1
        self.bytes += len(raw)
        if len(raw) > MAX_LINE_BYTES:
            self.overlong += 1
            return
        text = raw.decode("utf-8", "replace").rstrip("\r\n")
        # Docker is deliberately invoked without --timestamps; existing JSON is preserved.
        obj = None
        try:
            obj = json.loads(text)
            self.json_lines += 1
        except (ValueError, TypeError):
            pass
        event = access_event(obj, self.service)
        if event:
            status, latency, group = event
            self.groups[group].add(status, latency)
            for rid in request_ids(obj):
                if ID_RE.fullmatch(rid) and len(self.matched_request_ids) < MAX_SAMPLES:
                    self.matched_request_ids.add(rid)
        elif self.service == "api":
            match = ACCESS_RE.search(text)
            if match:
                ids = ID_RE.findall(text)
                self.groups[correlation(ids)].add(int(match[1]), None)
                self.matched_request_ids.update(ids[:5])
            else:
                self.unparsed += 1
        else:
            self.unparsed += 1
        if self.service == "api":
            # Fixed classifiers only; these are matching LINE counts, not incident counts.
            for name, regex in EXCEPTIONS:
                if regex.search(text):
                    self.exception_lines[name] += 1
                    line_sha = digest(raw)
                    if line_sha not in self.exception_hashes[name] and len(self.exception_hashes[name]) < 8:
                        self.exception_hashes[name].append(line_sha)
            frame = FRAME_RE.match(text)
            if frame:
                filename = frame[1].replace("\\", "/")
                for module, framework in FRAMEWORKS.items():
                    marker = "/" + module + "/"
                    if marker in filename:
                        suffix = module + "/" + filename.split(marker, 1)[1]
                        # Static Python source locations only; no source line/function arguments.
                        if len(suffix) <= 180 and re.fullmatch(r"[A-Za-z0-9_/.-]+\.py", suffix) and ".." not in suffix:
                            self.frames[(framework, suffix, int(frame[2]))] += 1
                        break

    def report(self):
        return {"service": self.service, "lines_seen": self.lines, "bytes_seen": self.bytes,
                "json_lines": self.json_lines, "lines_without_access_event": self.unparsed,
                "overlong_lines_discarded": self.overlong,
                "correlation": {name: agg.report() for name, agg in self.groups.items()},
                "distinct_matched_request_ids": len(self.matched_request_ids),
                "exception_matching_line_counts_unattributed": dict(self.exception_lines),
                "exception_line_sha256_samples": dict(self.exception_hashes),
                "traceback_source_frames_unattributed": [
                    {"framework": k[0], "source": k[1], "line": k[2], "matching_lines": n}
                    for k, n in self.frames.most_common(100)],
                "interpretation": "Unattributed events/tracebacks belong only to the selected time window, not proven to this load run. Exception categories may overlap on one line."}


def collect_logs(container_id, service, since, until):
    summary = LogSummary(service)
    started = time.monotonic()
    truncation = None
    try:
        process = subprocess.Popen(["docker", "logs", "--since", since, "--until", until, container_id],
                                   stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    except OSError:
        return {"service": service, "error": "DOCKER_LOGS_UNAVAILABLE"}
    selector = selectors.DefaultSelector()
    buffers = {}
    discarding = set()
    for pipe in (process.stdout, process.stderr):
        selector.register(pipe, selectors.EVENT_READ)
        buffers[pipe] = bytearray()
    total = 0
    try:
        while selector.get_map():
            if time.monotonic() - started > 90:
                truncation = "LOG_COLLECTION_TIMEOUT"
                break
            ready = selector.select(timeout=.25)
            for key, _ in ready:
                chunk = key.fileobj.read1(65536)
                if not chunk:
                    remaining = buffers.pop(key.fileobj)
                    if remaining:
                        summary.consume(bytes(remaining))
                    selector.unregister(key.fileobj)
                    continue
                total += len(chunk)
                if total > MAX_LOG_BYTES:
                    truncation = "LOG_BYTE_BUDGET"
                    break
                buffer = buffers[key.fileobj]
                if key.fileobj in discarding:
                    _, separator, chunk = chunk.partition(b"\n")
                    if not separator:
                        continue
                    discarding.remove(key.fileobj)
                buffer.extend(chunk)
                while b"\n" in buffer:
                    line, _, tail = buffer.partition(b"\n")
                    summary.consume(bytes(line))
                    buffer[:] = tail
                if len(buffer) > MAX_LINE_BYTES:
                    # A giant line is not retained; discard its rest until next newline.
                    summary.overlong += 1
                    buffer.clear()
                    discarding.add(key.fileobj)
            if truncation:
                break
    finally:
        selector.close()
        if truncation and process.poll() is None:
            process.kill()
        try:
            process.wait(timeout=5)
        except subprocess.TimeoutExpired:
            process.kill()
            process.wait(timeout=5)
        process.stdout.close()
        process.stderr.close()
    result = summary.report()
    result.update({"docker_logs_exit_code": process.returncode, "truncated": truncation is not None,
                   "truncation_reason": truncation, "collection_seconds": round(time.monotonic() - started, 3)})
    return result


INSPECT_TEMPLATE = r'''{"id":{{json .Id}},"name":{{json .Name}},"image":{{json .Image}},"service":{{json (index .Config.Labels "com.docker.compose.service")}},"status":{{json .State.Status}},"running":{{json .State.Running}},"restarting":{{json .State.Restarting}},"oom_killed":{{json .State.OOMKilled}},"restart_count":{{json .RestartCount}},"started_at":{{json .State.StartedAt}},"finished_at":{{json .State.FinishedAt}},"health":{{if .State.Health}}{{json .State.Health.Status}}{{else}}null{{end}},"memory_limit_bytes":{{json .HostConfig.Memory}},"nano_cpus":{{json .HostConfig.NanoCpus}}}'''


def percent(value):
    match = re.fullmatch(r"([0-9]+(?:\.[0-9]+)?)%", str(value))
    return float(match[1]) if match else None


def human_bytes(value):
    match = re.fullmatch(r"\s*([0-9]+(?:\.[0-9]+)?)\s*([kKMGT]?i?B)\s*", str(value))
    if not match:
        return None
    units = {"B": 1, "kB": 1000, "KB": 1000, "MB": 1000**2, "GB": 1000**3,
             "TB": 1000**4, "KiB": 1024, "MiB": 1024**2, "GiB": 1024**3, "TiB": 1024**4}
    return round(float(match[1]) * units[match[2]]) if match[2] in units else None


def inventory():
    raw, receipt = command(["docker", "ps", "-aq", "--filter", "label=com.docker.compose.project=" + PROJECT])
    ids = [s for s in raw.decode("ascii", "ignore").splitlines() if re.fullmatch(r"[0-9a-f]{12,64}", s)]
    if not ids or len(ids) > 30:
        return [], {"discovery": receipt, "error": "EXPECTED_COMPOSE_CONTAINERS_NOT_FOUND"}
    raw, inspect_receipt = command(["docker", "inspect", "--format", INSPECT_TEMPLATE, *ids])
    containers = []
    for line in raw.splitlines():
        try:
            item = json.loads(line)
            if not isinstance(item, dict) or not re.fullmatch(r"[0-9a-f]{64}", item.get("id", "")):
                continue
            # All fields originate from the explicit safe template, not whole inspect.
            containers.append(item)
        except (ValueError, TypeError):
            continue
    raw, stats_receipt = command(["docker", "stats", "--no-stream", "--format", "{{json .}}", *ids], timeout=20)
    stats = []
    for line in raw.splitlines():
        try:
            item = json.loads(line)
            if not isinstance(item, dict):
                continue
            name = item.get("Name", "")
            if not re.fullmatch(r"[A-Za-z0-9_.-]{1,150}", name):
                continue
            memory = str(item.get("MemUsage", "")).split("/", 1)
            pids = str(item.get("PIDs", ""))
            stats.append({"name": name, "cpu_percent": percent(item.get("CPUPerc")),
                          "memory_percent": percent(item.get("MemPerc")),
                          "memory_usage_bytes": human_bytes(memory[0]),
                          "memory_limit_bytes": human_bytes(memory[1]) if len(memory) == 2 else None,
                          "pids": int(pids) if re.fullmatch(r"\d{1,8}", pids) else None})
        except (ValueError, TypeError):
            continue
    resource = {"containers": stats,
                "cpu_percent_sum": round(sum(s["cpu_percent"] or 0 for s in stats), 3),
                "memory_usage_bytes_sum": sum(s["memory_usage_bytes"] or 0 for s in stats),
                "pids_sum": sum(s["pids"] or 0 for s in stats),
                "scope": "Current point-in-time docker stats; not historical load-window telemetry."}
    return containers, {"discovery": receipt, "inspect": inspect_receipt, "stats": stats_receipt, "resources": resource}


def self_test():
    sample = LogSummary("caddy")
    sample.consume(json.dumps({"status": 503, "duration": 2.25, "request": {"headers": {
        "Cookie": ["NEVER_OUTPUT_COOKIE"], "Authorization": ["Bearer NEVER_OUTPUT_TOKEN"],
        "X-Request-Id": [RUN_ID + "-abc"]}, "uri": "/PII_PRIVATE_PATH"}, "body": "NEVER_OUTPUT_BODY"}).encode())
    sample.consume(json.dumps({"status": 200, "duration": .01, "request": {"headers": {"X-Request-Id": ["another-run"]}}}).encode())
    sample.consume(b'{"status":200,"duration":0.02}')
    report = sample.report()
    assert report["correlation"]["matched_run"]["statuses"] == {"503": 1}
    assert report["correlation"]["matched_run"]["latency_p95_ms"] == 2250
    assert report["correlation"]["other_request_id"]["access_events"] == 1
    assert report["correlation"]["unattributed_no_request_id"]["access_events"] == 1
    api = LogSummary("api")
    api.consume(b'sqlalchemy.exc.TimeoutError: QueuePool limit reached SQL PARAMETERS NEVER_OUTPUT_SQL')
    api.consume(b'  File "/workspace/src/go_hotel/services/search.py", line 42, in secret_user_name')
    api.consume(b'INFO: remote_private_ip - "GET /private_user_email HTTP/1.1" 500 Internal Server Error')
    serial = json.dumps([report, api.report()])
    assert not any(secret in serial for secret in ["NEVER_OUTPUT", "PII_PRIVATE_PATH", "secret_user_name", "private_user_email", "remote_private_ip"])
    assert api.report()["exception_matching_line_counts_unattributed"]["SQLALCHEMY_QUEUE_POOL_TIMEOUT"] == 1
    assert api.report()["traceback_source_frames_unattributed"][0]["source"] == "go_hotel/services/search.py"
    assert correlation([RUN_ID + "-abc-other"]) == "other_request_id"
    assert human_bytes(" 1.25 GiB") == 1342177280
    print("SELF_TEST_PASS")


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--since", default=EARLIEST)
    parser.add_argument("--until")
    parser.add_argument("--run-id", default=RUN_ID)
    parser.add_argument("--self-test", action="store_true")
    args = parser.parse_args()
    if args.self_test:
        self_test()
        return 0
    try:
        start, end = utc(args.since), utc(args.until or "")
        if args.run_id != RUN_ID or start < utc(EARLIEST) or end <= start or (end - start).total_seconds() > MAX_WINDOW_SECONDS:
            raise ValueError("RUN_WINDOW_REJECTED")
        if end > dt.datetime.now(dt.timezone.utc) + dt.timedelta(seconds=5):
            raise ValueError("FUTURE_END_TIME_REJECTED")
    except ValueError:
        print(json.dumps({"error": "VALID_FIXED_RUN_UTC_WINDOW_REQUIRED"}))
        return 2
    containers, observations = inventory()
    logs = []
    for service in ("api", "caddy"):
        selected = [c for c in containers if c.get("service") == service and c.get("running") is True]
        if not selected:
            logs.append({"service": service, "error": "RUNNING_SERVICE_NOT_FOUND_IN_FIXED_PROJECT"})
            continue
        for container in selected:
            record = collect_logs(container["id"], service, args.since, args.until)
            record["container_id"] = container["id"]
            logs.append(record)
    result = {"schema_version": 1, "collector": "READ_ONLY_FIXED_RUN_SAFE_LOG_SUMMARY",
              "run_id": RUN_ID, "compose_project": PROJECT, "window": {"since": args.since, "until": args.until},
              "collected_at": dt.datetime.now(dt.timezone.utc).isoformat().replace("+00:00", "Z"),
              "containers": containers, "observations": observations, "logs": logs,
              "privacy": "No raw log lines, request headers/body, SQL parameters, IP addresses, credentials or response bodies are emitted.",
              "limitations": ["Exception/source-frame counts are time-window observations, not automatically attributed to this run.",
                              "Request attribution requires an exact matching load-run request ID.",
                              "Missing access-log request IDs or missing latency remain explicitly unavailable.",
                              "Container/resource observations are current, not historical snapshots."]}
    print(json.dumps(result, ensure_ascii=True, indent=2))
