class MatchedSummary(LogSummary):
    def __init__(self, service):
        super().__init__(service)
        self.kinds = collections.defaultdict(Aggregate)
        self.deltas = collections.defaultdict(list)
        self.seen = set()
        self.timeouts = []
    def consume(self, raw):
        super().consume(raw)
        try: obj = json.loads(raw)
        except (ValueError, TypeError): return
        event = access_event(obj, self.service)
        if not event: return
        for rid in request_ids(obj):
            if rid not in SELECTED or rid in self.seen: continue
            self.seen.add(rid)
            row=SELECTED[rid]; status, latency, _=event
            self.kinds[row['kind']].add(status,latency)
            if latency is not None: self.deltas[row['kind']].append(row['client_ms']-latency)
            if row['client_status']==0: self.timeouts.append({'kind':row['kind'],'server_status':status,'server_ms':latency,'client_ms':row['client_ms']})
    def report(self):
        r=super().report()
        r['selected_500_requests']=len(SELECTED)
        r['matched_500_requests']=len(self.seen)
        r['unmatched_500_by_kind']=dict(collections.Counter(SELECTED[k]['kind'] for k in SELECTED if k not in self.seen))
        r['per_kind_500']={k:v.report() for k,v in self.kinds.items()}
        r['client_minus_server_ms']={k:{'min':round(min(v),3),'mean':round(sum(v)/len(v),3),'max':round(max(v),3)} for k,v in self.deltas.items()}
        r['client_timeouts_matched']=self.timeouts
        return r
